[sj@kernel.org: let kdamond_call() with cancel regardless of maybe_corrupted]
  Link: https://lkml.kernel.org/r/20260320031553.2479-1-sj@kernel.org
  Link: https://sashiko.dev/#/patchset/20260319145218.86197-1-sj%40kernel.org
Link: https://lkml.kernel.org/r/20260319145218.86197-1-sj@kernel.org
Link: https://lore.kernel.org/20260319043309.97966-1-sj@kernel.org [1]
Fixes: 3301f1861d34 ("mm/damon/sysfs: handle commit command using damon_call()")
Signed-off-by: SeongJae Park <sj@kernel.org>
Cc: <stable@vger.kernel.org>	[6.15+]
Signed-off-by: Andrew Morton <akpm@linux-foundation.org>

Here is the root cause:
damon_commit_ctx() updates the DAMON context incrementally; if it fails partway (e.g., due to memory allocation failure), the context is left in a partially updated, inconsistent state. Previously, there was no safeguard to detect or prevent subsequent use of this corrupted context, allowing the kdamond thread to continue operating on it and potentially cause null pointer dereferences or other undefined behavior.

Here is the patch:
  */
 int damon_commit_ctx(struct damon_ctx *dst, struct damon_ctx *src)
 {
 	int err;

+	dst->maybe_corrupted = true;
 	if (!is_power_of_2(src->min_region_sz))
 		return -EINVAL;

 	err = damon_commit_schemes(dst, src);
 	if (err)
 		return err;
 	err = damon_commit_targets(dst, src);
 	if (err)
 		return err;
 	/*
 	 * schemes and targets should be updated first, since
 	 * 1. damon_set_attrs() updates monitoring results of targets and
 	 * next_apply_sis of schemes, and
 	 * 2. ops update should be done after pid handling is done (target
 	 *    committing require putting pids).
 	 */
 	if (!damon_attrs_equals(&dst->attrs, &src->attrs)) {
 		err = damon_set_attrs(dst, &src->attrs);
 		if (err)
 			return err;
 	}
 	dst->ops = src->ops;
 	dst->addr_unit = src->addr_unit;
 	dst->min_region_sz = src->min_region_sz;

+	dst->maybe_corrupted = false;
 	return 0;
 }

  */
 static void kdamond_call(struct damon_ctx *ctx, bool cancel)
 {
 	struct damon_call_control *control, *next;
 	LIST_HEAD(controls);

 	mutex_lock(&ctx->call_controls_lock);
 	list_splice_tail_init(&ctx->call_controls, &controls);
 	mutex_unlock(&ctx->call_controls_lock);

 	list_for_each_entry_safe(control, next, &controls, list) {
 		if (!control->repeat || cancel)
 			list_del(&control->list);

 		if (cancel)
 			control->canceled = true;
 		else
 			control->return_code = control->fn(control->data);

 		if (!control->repeat)
 			complete(&control->completion);
 		else if (control->canceled && control->dealloc_on_cancel)
 			kfree(control);
+		if (!cancel && ctx->maybe_corrupted)
+			break;
 	}

 	mutex_lock(&ctx->call_controls_lock);
 	list_splice_tail(&controls, &ctx->call_controls);
 	mutex_unlock(&ctx->call_controls_lock);
 }

 /* Returns negative error code if it's not activated but should return */
 static int kdamond_wait_activation(struct damon_ctx *ctx)
 {
 	struct damos *s;
 	unsigned long wait_time;
 	unsigned long min_wait_time = 0;
 	bool init_wait_time = false;

 	while (!kdamond_need_stop(ctx)) {
 		damon_for_each_scheme(s, ctx) {
 			wait_time = damos_wmark_wait_us(s);
 			if (!init_wait_time || wait_time < min_wait_time) {
 				init_wait_time = true;
 				min_wait_time = wait_time;
 			}
 		}
 		if (!min_wait_time)
 			return 0;

 		kdamond_usleep(min_wait_time);

 		kdamond_call(ctx, false);
+		if (ctx->maybe_corrupted)
+			return -EINVAL;
 		damos_walk_cancel(ctx);
 	}
 	return -EBUSY;
 }

  */
 static int kdamond_fn(void *data)
 {
 	struct damon_ctx *ctx = data;
 	unsigned int max_nr_accesses = 0;
 	unsigned long sz_limit = 0;

 	pr_debug("kdamond (%d) starts\n", current->pid);

 	complete(&ctx->kdamond_started);
 	kdamond_init_ctx(ctx);

 	if (ctx->ops.init)
 		ctx->ops.init(ctx);
 	ctx->regions_score_histogram = kmalloc_array(DAMOS_MAX_SCORE + 1,
 			sizeof(*ctx->regions_score_histogram), GFP_KERNEL);
 	if (!ctx->regions_score_histogram)
 		goto done;

 	sz_limit = damon_region_sz_limit(ctx);

 	while (!kdamond_need_stop(ctx)) {
 		/*
 		 * ctx->attrs and ctx->next_{aggregation,ops_update}_sis could
 		 * be changed from kdamond_call().  Read the values here, and
 		 * use those for this iteration.  That is, damon_set_attrs()
 		 * updated new values are respected from next iteration.
 		 */
 		unsigned long next_aggregation_sis = ctx->next_aggregation_sis;
 		unsigned long next_ops_update_sis = ctx->next_ops_update_sis;
 		unsigned long sample_interval = ctx->attrs.sample_interval;

 		if (kdamond_wait_activation(ctx))
 			break;

 		if (ctx->ops.prepare_access_checks)
 			ctx->ops.prepare_access_checks(ctx);

 		kdamond_usleep(sample_interval);
 		ctx->passed_sample_intervals++;

 		if (ctx->ops.check_accesses)
 			max_nr_accesses = ctx->ops.check_accesses(ctx);

 		if (ctx->passed_sample_intervals >= next_aggregation_sis)
 			kdamond_merge_regions(ctx,
 					max_nr_accesses / 10,
 					sz_limit);

 		/*
 		 * do kdamond_call() and kdamond_apply_schemes() after
 		 * kdamond_merge_regions() if possible, to reduce overhead
 		 */
 		kdamond_call(ctx, false);
+		if (ctx->maybe_corrupted)
+			break;
 		if (!list_empty(&ctx->schemes))
 			kdamond_apply_schemes(ctx);
 		else
 			damos_walk_cancel(ctx);

 		sample_interval = ctx->attrs.sample_interval ?
 			ctx->attrs.sample_interval : 1;
 		if (ctx->passed_sample_intervals >= next_aggregation_sis) {
 			if (ctx->attrs.intervals_goal.aggrs &&
 					ctx->passed_sample_intervals >=
 					ctx->next_intervals_tune_sis) {
 				/*
 				 * ctx->next_aggregation_sis might be updated
 				 * from kdamond_call().  In the case,
 				 * damon_set_attrs() which will be called from
 				 * kdamond_tune_interval() may wrongly think
 				 * this is in the middle of the current
 				 * aggregation, and make aggregation
 				 * information reset for all regions.  Then,
 				 * following kdamond_reset_aggregated() call
 				 * will make the region information invalid,
 				 * particularly for ->nr_accesses_bp.
 				 *
 				 * Reset ->next_aggregation_sis to avoid that.
 				 * It will anyway correctly updated after this
 				 * if clause.
 				 */
 				ctx->next_aggregation_sis =
 					next_aggregation_sis;
