static void damon_warn_fix_nr_accesses_corruption(struct damon_region *r)
{
	if (r->nr_accesses_bp == r->nr_accesses * 10000)
		return;
	WARN_ONCE(true, "invalid nr_accesses_bp at reset: %u %u\n",
			r->nr_accesses_bp, r->nr_accesses);
